\begin{tikzpicture}[font=\sffamily\small,line cap=round,line join=round,>=stealth]
% Concave mirror facing sunlight
\draw[thick] (2.2,0.3) .. controls (0.6,1.7) .. (2.2,3.1);
\foreach \y in {0.6,1.1,1.6,2.1,2.6} {\draw[thin] (2.05,\y)--(2.25,\y+0.12);}
\node[font=\bfseries] at (2.9,3.35) {concave mirror};
% Parallel sun rays in
\draw[->,thick] (6.2,2.7)--(2.05,2.7);
\draw[->,thick] (6.2,1.7)--(1.55,1.7);
\draw[->,thick] (6.2,0.7)--(2.05,0.7);
\node at (6.5,1.7) {Sun};
% Reflected rays meet on paper
\draw[->,thick] (2.05,2.7)--(0.55,1.7);
\draw[->,thick] (1.55,1.7)--(0.45,1.7);
\draw[->,thick] (2.05,0.7)--(0.55,1.7);
\fill (0.5,1.7) circle (1.5pt);
\draw[thick,fill=white] (-0.15,1.35) rectangle (0.35,2.05);
\node[font=\footnotesize] at (0.1,1.05) {paper};
\end{tikzpicture}
